import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // API route for Gemini text expansion
  app.post("/api/expand-notes", async (req, res) => {
    try {
      const { keywords, context } = req.body;
      
      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey) {
        return res.status(500).json({ error: "API key is not configured." });
      }

      const ai = new GoogleGenAI({
        apiKey,
        httpOptions: {
          headers: {
            'User-Agent': 'aistudio-build',
          }
        }
      });

      const prompt = `Tu es un assistant spécialisé en Santé, Sécurité au Travail et enquêtes CSE/CSSCT. 
Un utilisateur a pris des notes très rapides (Mots clés) sur le terrain.
Contexte du champ : ${context}
Notes : ${keywords}

Retranscris ces mots-clés en une ou plusieurs phrases complètes, claires, professionnelles et objectives, adaptées à un rapport officiel. Ne rajoute pas d'informations inventées. Garde un ton neutre et factuel.
IMPORTANT : Fournis UNIQUEMENT LA RETRANSCRIPTION STANDARD DIRECTEMENT, sans aucune introduction (comme "Voici la retranscription"), sans options multiples (option 1 uniquement), et sans commentaires. Juste le texte final.`;

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
      });

      res.json({ text: response.text });
    } catch (error) {
      console.error("Gemini API Error:", error);
      res.status(500).json({ error: "Failed to generate text" });
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
